SELECT 'gongkao', '损耗与返工', 'kp-eng-ct-loss-rework', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "损耗与返工"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "一边干活一边搞破坏（或出现次品需要重做）。等效于“净效率下降”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经典代表就是传说中的“青蛙爬井”（白天上爬晚上滑下）或者“水池进出水”（一边注水一边漏水）。在工程问题中体现为“产生次品要扣除或返工”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "将“破坏/损耗”视为一个效率为负的参与者。"}]}, {"type": "katexBlock", "attrs": {"content": "P_{净} = P_{正向建设} - P_{负向破坏}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[识别出存在搞破坏的元素] --> B[算出正向效率 P正 和负向效率 P负]\nB --> C[算出净推进效率 P净 = P正 - P负]\nC --> D{是否存在最后一步跨越登顶的情况?}\nD -- 青蛙爬井型 --> E[扣除最后一次不被破坏的余量: W - P正]\nE --> F[用剩余量除以 P净, 再加上最后这一次]\nD -- 同步漏水型 --> G[直接用 W总 ÷ P净 求解]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 一个水池，单开进水管 10 小时注满，单开漏水管 15 小时漏光。两管齐开，几小时注满？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋总量：10 和 15 的公倍数 W = 30。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出效率：进水 P正 = 3；漏水 P负 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算净效率：P净 = 3 - 2 = 1。即两管齐开，每小时池子里只多出 1 的水。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求总时间：T = 30 ÷ 1 = 30 小时。选 30。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "青蛙爬井的最后一步跨越：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果题目是“白天修 5 米，晚上冲毁 2 米。路长 30 米”。千万不能直接 30 ÷ 3 = 10 天！因为在第 9 天白天修完 5 米时，总长度就已经达到 24 + 5 = 29 米。到第 10 天白天，修 1 米就登顶完工了，不会再被冲毁！必须用公式：(总长 - 纯白天) / 净效率 + 1。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把“一边进一边漏”和“交替进和漏（青蛙爬井）”严格区分开。前者直接除，后者必须扣尾巴。"}]}]}$$ AS jsonb), NULL, '损耗与返工的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "损耗与返工"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_ct_loss_rework", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
